// Writing text with a font texture. iTexture0 is a font: a grid of 16 x 6 characters, from !
// (code 33) to ~ (code 126) in ASCII order. Pick another font in the [Textures] tab.

// How high the letters bounce. Try it in the [Sliders] tab.
#define waveHeight iFloat0

// The message, as ASCII codes: S M O O T H S T E P.
#define LENGTH 10
const int MESSAGE[LENGTH] = int[](83, 77, 79, 79, 84, 72, 83, 84, 69, 80);

// How much ink character `code` has at p, where p runs from 0 to 1 across its square.
float character(int code, vec2 p) {
  if (p.x < 0.0 || p.y < 0.0 || p.x > 1.0 || p.y > 1.0) {
    return 0.0;
  }
  // Which square of the grid the character is in. Row 0 is the top row of the image.
  int index = code - 33;
  vec2 square = vec2(index % 16, 5 - index / 16);
  // The font is black on white, so ink is 1 minus the brightness.
  float ink = 1.0 - texture(iTexture0, (square + p) / vec2(16.0, 6.0)).r;
  // The font is small, so its edges blur when it's drawn big. smoothstep sharpens them again.
  return smoothstep(0.35, 0.65, ink);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Centred coordinates: y runs from -1 to 1.
  vec2 p = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

  // A dark background, a little lighter at the top.
  vec3 col = mix(vec3(0.05, 0.05, 0.1), vec3(0.15, 0.1, 0.25), 0.5 + 0.5 * p.y);

  // How far through the animation we are, from 0 to 1, so that it loops.
  float t = iTime / iDuration;
  float size = 0.6;      // The height of each character's square.
  float spacing = 0.5 * size;

  for (int i = 0; i < LENGTH; i++) {
    // Each letter bounces a little after the one before it.
    float x = (float(i) - 0.5 * float(LENGTH - 1)) * spacing;
    float y = waveHeight * sin(6.28318 * (2.0 * t - 0.08 * float(i)));
    // Where this pixel is in the letter's square, from 0 to 1.
    vec2 q = (p - vec2(x, y)) / size + 0.5;

    float shadow = character(MESSAGE[i], q + vec2(-0.04, 0.05));
    float ink = character(MESSAGE[i], q);
    vec3 letterColour = 0.6 + 0.4 * cos(6.28318 * (t + 0.08 * float(i)) + vec3(0.0, 2.0, 4.0));

    col = mix(col, vec3(0.0), 0.6 * shadow);
    col = mix(col, letterColour, ink);
  }

  fragColor = vec4(col, 1.0);
}
